package com.meowcape.healthmarkers;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(HealthMarkersConfig.GROUP)
public interface HealthMarkersConfig extends Config
{
	String GROUP = "healthmarkers";

	@ConfigItem(
		keyName = "markers",
		name = "Markers",
		description = "One NPC per line: Name: 25, 50, 75 (lines can end with ;)<br>"
			+ "Values are health PERCENTAGES (0-100), not hitpoints. Decimals like 66.6 are fine.<br>"
			+ "Use * as a wildcard (e.g. *: 50 marks every NPC at 50%).<br>"
			+ "Add #RRGGBB or #AARRGGBB at the end of a line to give it its own colour.<br>"
			+ "An NPC can have several lines; all matching lines are drawn.",
		position = 0
	)
	default String markers()
	{
		return "Akkha: 20, 40, 60, 80;\n"
			+ "\n"
			+ "Alchemical Hydra: 75 #730088FF;\n"
			+ "Alchemical Hydra: 50 #73FF0000;\n"
			+ "Alchemical Hydra: 25 #73A0A0A0;\n"
			+ "\n"
			+ "Ba-Ba: 66.6, 33.3\n"
			+ "\n"
			+ "Corrupted Hunllef: 66.6, 32;\n"
			+ "\n"
			+ "Maggot King: 66.6;\n"
			+ "Maggot King: 20 #73FF0000;";
	}

	@Alpha
	@ConfigItem(
		keyName = "markerColor",
		name = "Marker colour",
		description = "Default colour of the markers",
		position = 1
	)
	default Color markerColor()
	{
		return new Color(255, 255, 255, 0x73);
	}

	@Range(min = 1, max = 5)
	@ConfigItem(
		keyName = "markerWidth",
		name = "Marker width",
		description = "Thickness of each marker in pixels",
		position = 2
	)
	default int markerWidth()
	{
		return 1;
	}

	@ConfigItem(
		keyName = "hidePassed",
		name = "Hide passed markers",
		description = "Hide markers once the opponent's health has dropped below them",
		position = 3
	)
	default boolean hidePassed()
	{
		return false;
	}
}

package com.meowcape.healthmarkers;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws markers on top of RuneLite's Opponent Information health bar.
 *
 * The Opponent Information overlay is a panel with a 2px border, the opponent's name,
 * a 2px gap and then a 16px health bar as its last row, so the bar's position can be
 * worked out from the panel's on-screen bounds.
 */
class HealthMarkersOverlay extends Overlay
{
	private static final String OPPONENT_OVERLAY_NAME = "OpponentInfoOverlay";
	private static final int PANEL_BORDER = 2;
	private static final int BAR_HEIGHT = 16;

	private final HealthMarkersPlugin plugin;
	private final HealthMarkersConfig config;
	private final OverlayManager overlayManager;

	@Inject
	HealthMarkersOverlay(HealthMarkersPlugin plugin, HealthMarkersConfig config, OverlayManager overlayManager)
	{
		this.plugin = plugin;
		this.config = config;
		this.overlayManager = overlayManager;
		setPosition(OverlayPosition.DYNAMIC);
		// Must be drawn after (on top of) the Opponent Information panel. When that panel is dragged
		// out of its corner, RuneLite moves it up to the ABOVE_WIDGETS layer, so use the top layer.
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
		setPriority(PRIORITY_LOW);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		List<MarkerRule> rules = plugin.getActiveRules();
		if (rules.isEmpty())
		{
			return null;
		}

		Rectangle panel = findOpponentPanel();
		if (panel == null || panel.width <= 0 || panel.height <= BAR_HEIGHT + PANEL_BORDER * 2)
		{
			return null;
		}

		int barX = panel.x + PANEL_BORDER;
		int barY = panel.y + panel.height - PANEL_BORDER - BAR_HEIGHT;
		int barWidth = panel.width - PANEL_BORDER * 2;

		int width = config.markerWidth();
		double health = plugin.getHealthFraction();

		for (MarkerRule rule : rules)
		{
			graphics.setColor(rule.color != null ? rule.color : config.markerColor());
			for (double percent : rule.percents)
			{
				if (config.hidePassed() && health >= 0 && health * 100 < percent)
				{
					continue;
				}

				int x = barX + (int) Math.round(barWidth * percent / 100.0) - width / 2;
				graphics.fillRect(x, barY, width, BAR_HEIGHT);
			}
		}

		return null;
	}

	/**
	 * Finds the on-screen bounds of the Opponent Information panel, or null if it isn't showing.
	 */
	private Rectangle findOpponentPanel()
	{
		Rectangle[] found = new Rectangle[1];
		overlayManager.anyMatch(o ->
		{
			if (OPPONENT_OVERLAY_NAME.equals(o.getName()))
			{
				found[0] = o.getBounds();
				return true;
			}
			return false;
		});
		return found[0];
	}
}

package com.meowcape.healthmarkers;

import com.google.inject.Provides;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.events.GameTick;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@PluginDescriptor(
	name = "Opponent Health Markers",
	description = "Draws boss phase markers on RuneLite's Opponent Information health bar",
	tags = {"boss", "health", "hp", "phase", "markers", "opponent", "indicators"}
)
public class HealthMarkersPlugin extends Plugin
{
	// Opponent Information hides its panel 5 seconds after you stop fighting; match that
	private static final Duration OPPONENT_TIMEOUT = Duration.ofSeconds(5);

	@Inject
	private Client client;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private HealthMarkersOverlay overlay;

	@Inject
	private HealthMarkersConfig config;

	private List<MarkerRule> rules = Collections.emptyList();

	private NPC opponent;
	private Instant lastInteraction;

	/** Last known health of the opponent, 0-1, or -1 if unknown */
	private double healthFraction = -1;

	@Provides
	HealthMarkersConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(HealthMarkersConfig.class);
	}

	@Override
	protected void startUp()
	{
		rules = MarkerRule.parse(config.markers());
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		opponent = null;
		lastInteraction = null;
		healthFraction = -1;
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (HealthMarkersConfig.GROUP.equals(event.getGroup()))
		{
			rules = MarkerRule.parse(config.markers());
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (client.getLocalPlayer() == null)
		{
			return;
		}

		Actor target = client.getLocalPlayer().getInteracting();
		if (target instanceof NPC)
		{
			if (target != opponent)
			{
				healthFraction = -1;
			}
			opponent = (NPC) target;
			lastInteraction = Instant.now();
		}

		if (opponent != null)
		{
			int ratio = opponent.getHealthRatio();
			int scale = opponent.getHealthScale();
			if (ratio >= 0 && scale > 0)
			{
				healthFraction = ratio / (double) scale;
			}

			if (lastInteraction != null && Duration.between(lastInteraction, Instant.now()).compareTo(OPPONENT_TIMEOUT) > 0)
			{
				opponent = null;
				healthFraction = -1;
			}
		}
	}

	/**
	 * @return every marker line that matches the current opponent (empty if none)
	 */
	List<MarkerRule> getActiveRules()
	{
		NPC npc = opponent;
		if (npc == null || npc.getName() == null)
		{
			return Collections.emptyList();
		}

		String name = Text.removeTags(npc.getName());
		List<MarkerRule> matching = new ArrayList<>();
		for (MarkerRule rule : rules)
		{
			if (rule.matches(name))
			{
				matching.add(rule);
			}
		}
		return matching;
	}

	double getHealthFraction()
	{
		return healthFraction;
	}
}

package com.meowcape.healthmarkers;

import java.awt.Color;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.regex.Pattern;

/**
 * One line of the markers config: an NPC name pattern, its health percentages and an optional colour.
 */
final class MarkerRule
{
	final Pattern name;
	final double[] percents;
	final Color color;

	private MarkerRule(Pattern name, double[] percents, Color color)
	{
		this.name = name;
		this.percents = percents;
		this.color = color;
	}

	boolean matches(String npcName)
	{
		return name.matcher(npcName.toLowerCase(Locale.ROOT)).matches();
	}

	/**
	 * Parses the config text. Bad lines are skipped rather than breaking the whole list.
	 */
	static List<MarkerRule> parse(String text)
	{
		List<MarkerRule> rules = new ArrayList<>();
		if (text == null)
		{
			return rules;
		}

		// Entries are separated by new lines and/or ";"
		for (String rawLine : text.split("\\r?\\n|;"))
		{
			String line = rawLine.trim();
			int colon = line.lastIndexOf(':');
			if (line.isEmpty() || line.startsWith("//") || colon <= 0)
			{
				continue;
			}

			String namePart = line.substring(0, colon).trim();
			String valuePart = line.substring(colon + 1).trim();

			Color color = null;
			int hash = valuePart.indexOf('#');
			if (hash >= 0)
			{
				color = parseColor(valuePart.substring(hash + 1).trim());
				valuePart = valuePart.substring(0, hash);
			}

			List<Double> values = new ArrayList<>();
			for (String v : valuePart.split(","))
			{
				String s = v.trim().replace("%", "");
				if (s.isEmpty())
				{
					continue;
				}
				try
				{
					double d = Double.parseDouble(s);
					if (d > 0 && d < 100)
					{
						values.add(d);
					}
				}
				catch (NumberFormatException ignored)
				{
				}
			}

			if (namePart.isEmpty() || values.isEmpty())
			{
				continue;
			}

			double[] percents = new double[values.size()];
			for (int i = 0; i < percents.length; i++)
			{
				percents[i] = values.get(i);
			}

			rules.add(new MarkerRule(wildcard(namePart), percents, color));
		}
		return rules;
	}

	private static Pattern wildcard(String name)
	{
		// "*" matches anything; everything else must match literally
		List<String> parts = new ArrayList<>();
		for (String part : name.toLowerCase(Locale.ROOT).split("\\*", -1))
		{
			parts.add(Pattern.quote(part));
		}
		return Pattern.compile(String.join(".*", parts));
	}

	private static Color parseColor(String hex)
	{
		try
		{
			if (hex.length() == 6)
			{
				return new Color(Integer.parseInt(hex, 16));
			}
			if (hex.length() == 8)
			{
				return new Color((int) Long.parseLong(hex, 16), true);
			}
		}
		catch (NumberFormatException ignored)
		{
		}
		return null;
	}
}

package com.meowcape.healthmarkers;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class HealthMarkersPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(HealthMarkersPlugin.class);
		RuneLite.main(args);
	}
}
